// Build area prompts: generated from n8n/mobilise/logic.mjs buildAreaPrompts. Edit there, then rebuild.
const __fn = function buildAreaPrompts(input) {
  const rows = input.checklist || []
  const out = []
  for (const a of input.checklist_areas || []) {
    const ls = rows.filter((r) => r.area === a.code)
    const lines = ls.map((l) => Number(l.code.split('-')[1]) + '. ' + l.text + (l.severity === 'critical' ? ' 🔴' : '')).join('\n')
    out.push({
      mobilisation_id: input.mobilisation_id, contact_id: input.contractor_contact_id, kind: 'area', area: a.code, line_code: '',
      request: { body: { type: 'text', text: { preview_url: false, body: '*' + a.name + ' (' + a.code + ')*\n' + lines + '\n\nReply to *this message* with photos or papers for ' + a.name + '. Write the number in the caption (e.g. 3).' } } },
    })
  }
  return out
};
const out = [];
const all = $input.all();
for (let i = 0; i < all.length; i++) {
  const item = all[i];
  let input = { ...item.json };
  input.checklist = $('Copy checklist for this site').first().json.checklist; input.checklist_areas = $('Copy checklist for this site').first().json.checklist_areas;
  for (const j of [].concat(__fn(input))) out.push({ json: j });
}
return out;

// Why Code: signs the engineer's walk link (HMAC, expires the day after the visit).
const crypto = require('crypto');
const item = $input.item;
const exp = Math.floor(Date.parse(item.json.visit_date + 'T23:59:59+05:30') / 1000) + 86400;
const base = item.json.walk_id + '.' + exp;
const token = base + '.' + crypto.createHmac('sha256', $env.VERA_WALK_SECRET || '').update(base).digest('base64url');
const url = ($env.VERA_WALK_URL || 'https://vera.example/walk') + '#t=' + token;
return { json: { ...item.json, request: {
  body: { type: 'text', text: { preview_url: false, body: '*Site visit ' + item.json.visit_date + ': ' + item.json.project + '*\nOpen this on the day. Tap a line, take the photo, say your remark. GPS is recorded with each photo.\n' + url } },
  template: { name: 'vera_mob_walk_link', language: 'en', params: [item.json.project, item.json.visit_date, url] } } } };
